#include <zephyr/ztest.h>
#include <zephyr/sys/multi_heap.h>

#define HEAP_SIZE (4 * 1024)

static struct multi_heap shared_heap;
static ZTEST_BMEM char backing_store[HEAP_SIZE];

static void *multi_heap_concept_setup(void)
{
	multi_heap_init(&shared_heap, (uintptr_t)backing_store, HEAP_SIZE);
	return NULL;
}

ZTEST(multi_heap_concept, test_alloc_free)
{
	void *block;

	block = multi_heap_alloc(&shared_heap, 128, K_NO_WAIT);
	zassert_not_null(block, "allocation failed");

	multi_heap_free(&shared_heap, block);
}

ZTEST(multi_heap_concept, test_alloc_too_big)
{
	void *block;

	block = multi_heap_alloc(&shared_heap, HEAP_SIZE * 2, K_NO_WAIT);
	zassert_is_null(block, "allocation should have failed");
}

ZTEST(multi_heap_concept, test_alloc_all)
{
	void *block;

	/*
	 * This will fail because of metadata overhead. The exact amount of
	 * overhead is an implementation detail, so we just check that
	 * allocating the full size fails.
	 */
	block = multi_heap_alloc(&shared_heap, HEAP_SIZE, K_NO_WAIT);
	zassert_is_null(block, "allocation should have failed");
}

ZTEST(multi_heap_concept, test_realloc_smaller)
{
	void *block;
	void *new_block;

	block = multi_heap_alloc(&shared_heap, 256, K_NO_WAIT);
	zassert_not_null(block, "allocation failed");

	new_block = multi_heap_realloc(&shared_heap, block, 128);
	zassert_not_null(new_block, "realloc failed");
	zassert_equal_ptr(block, new_block, "realloc should have been in-place");

	multi_heap_free(&shared_heap, new_block);
}

ZTEST(multi_heap_concept, test_realloc_larger)
{
	void *block;
	void *new_block;

	block = multi_heap_alloc(&shared_heap, 128, K_NO_WAIT);
	zassert_not_null(block, "allocation failed");

	new_block = multi_heap_realloc(&shared_heap, block, 256);
	zassert_not_null(new_block, "realloc failed");
	zassert_equal_ptr(block, new_block, "realloc should have been in-place");

	multi_heap_free(&shared_heap, new_block);
}

ZTEST(multi_heap_concept, test_realloc_null)
{
	void *block;

	block = multi_heap_realloc(&shared_heap, NULL, 128);
	zassert_not_null(block, "realloc(NULL) should be like alloc");

	multi_heap_free(&shared_heap, block);
}

ZTEST(multi_heap_concept, test_realloc_free)
{
	void *block;
	void *new_block;

	block = multi_heap_alloc(&shared_heap, 128, K_NO_WAIT);
	zassert_not_null(block, "allocation failed");

	new_block = multi_heap_realloc(&shared_heap, block, 0);
	zassert_is_null(new_block, "realloc(0) should be like free");
}

ZTEST_SUITE(multi_heap_concept, NULL, multi_heap_concept_setup, NULL, NULL, NULL);
